class Solution:
    def minimumSumSubarray(self, nums: List[int], l: int, r: int) -> int:
        n = len(nums)
        # Build prefix sum array
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        min_positive = float('inf')
        # Check every possible starting index
        for i in range(n):
            # Check every allowed length
            for length in range(l, r + 1):
                if i + length > n:
                    break
                current_sum = prefix[i + length] - prefix[i]
                if current_sum > 0:
                    min_positive = min(min_positive, current_sum)

        return min_positive if min_positive != float('inf') else -1

class Solution:
    def countServers(self, grid: list[list[int]]) -> int:
        m = len(grid)
        n = len(grid[0])

        # Count servers in each row and column
        row_counts = [0] * m
        col_counts = [0] * n

        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    row_counts[i] += 1
                    col_counts[j] += 1

        # Count servers that communicate (have at least one other server in row or column)
        result = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1 and (row_counts[i] > 1 or col_counts[j] > 1):
                    result += 1

        return result

class Solution:
    def findTheDistanceValue(self, arr1: list[int], arr2: list[int], d: int) -> int:
        arr2.sort()
        count = 0
        import bisect

        for x in arr1:
            # Find the first index in arr2 where value >= x
            idx = bisect.bisect_left(arr2, x)
            ok = True

            # Check the element at idx (first >= x)
            if idx < len(arr2) and arr2[idx] - x <= d:
                ok = False
            # Check the element just before idx (largest < x)
            if idx > 0 and x - arr2[idx - 1] <= d:
                ok = False

            if ok:
                count += 1

        return count

from typing import List

class Solution:
    def minMoves(self, nums: List[int]) -> int:
        """
        Returns the minimum number of moves to make all elements equal.
        Since we can only increment elements, the optimal target is the maximum element.
        The total moves is the sum of differences between max and each element.
        """
        max_val = max(nums)
        return sum(max_val - x for x in nums)

class Solution:
    def minMoves(self, nums: list[int]) -> int:
        total = sum(nums)
        min_val = min(nums)
        return total - min_val * len(nums)

class Solution:
    def minCost(self, grid: list[list[int]]) -> int:
        m, n = len(grid), len(grid[0])
        MAX_XOR = 1024  # grid values are <= 1023, so XOR stays within 0..1023

        # dp[i][j] is a bitset where bit x is 1 iff XOR value x is reachable at (i, j)
        dp = [[0] * n for _ in range(m)]
        dp[0][0] = 1 << grid[0][0]

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                val = grid[i][j]
                reachable = 0
                if i > 0:
                    reachable |= dp[i - 1][j]
                if j > 0:
                    reachable |= dp[i][j - 1]

                # Transform reachable XORs: new_xor = old_xor ^ val
                new_bits = 0
                for x in range(MAX_XOR):
                    if reachable & (1 << x):
                        new_bits |= 1 << (x ^ val)
                dp[i][j] = new_bits

        # Find the minimum reachable XOR at the bottom-right cell
        final_bits = dp[m - 1][n - 1]
        for x in range(MAX_XOR):
            if final_bits & (1 << x):
                return x
        return 0  # unreachable due to constraints

class Solution:
    def countIslands(self, grid: List[List[int]], k: int) -> int:
        if not grid or not grid[0]: return 0
        m, n, ans = len(grid), len(grid[0]), 0
        for r in range(m):
            for c in range(n):
                if grid[r][c] > 0:
                    s, stack = grid[r][c], [(r, c)]
                    grid[r][c] = 0
                    while stack:
                        cr, cc = stack.pop()
                        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] > 0:
                                s += grid[nr][nc]
                                grid[nr][nc] = 0
                                stack.append((nr, nc))
                    if s % k == 0:
                        ans += 1
        return ans

